function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4200)}
function safeURL(url){try{const u=new URL(url,location.href);return ['http:','https:','mailto:'].includes(u.protocol)?u.href:null}catch{return null}}
function link(url,label,cls=''){const u=safeURL(url);return u?`<a class="${cls}" href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:`<span>${esc(label)}</span>`}
