function loadDrafts(){if(readOnly)return;try{const stored=JSON.parse(localStorage.getItem('space-atlas-v6-drafts')||'{}');for(const [id,bundle] of Object.entries(stored)){try{p=C.upsert(b,p,bundle);drafts[id]=bundle;revision++}catch(e){console.warn('Draft not loaded:',id,e.message)}}}catch{}}
