function clearFocus(resetPicked=true){window.AtlasExperience?.stopFlow();$('#canvas').classList.remove('focus');svg?.querySelectorAll('.related,.picked').forEach(n=>n.classList.remove('related','picked'));if(resetPicked){picked=null;teamScope=null;welcomeDetail()}window.AtlasExperience?.flowAvailable()}
