function highlight(ids){const set=new Set(ids);$('#canvas').classList.add('focus');for(const e of svg.querySelectorAll('.edge')){const on=e.style.display!=='none'&&(set.has(e.dataset.source)||set.has(e.dataset.target));e.classList.toggle('related',on);if(on){set.add(e.dataset.source);set.add(e.dataset.target)}}for(const n of svg.querySelectorAll('.node'))n.classList.toggle('related',set.has(n.dataset.node))}
