function detail(html){$('#graph-shell').classList.remove('closed');$('#detail').innerHTML=`<div class="detail-tools"><span>${L('节点与连线介绍','Diagram details')}</span><button class="close" aria-label="${L('关闭介绍','Close details')}" data-close-detail>×</button></div>${html}`;$('#detail').scrollTop=0;window.AtlasExperience?.detailReady()}
function welcomeDetail(){detail(`<div class="eyebrow welcome-kicker">SPACE MATERIAL ATLAS</div><h2 class="welcome-lead">${L('太空物质循环图谱','Space material flows')}</h2><p>${L('图谱展示太空系统中的物质与工艺，以及 iGEM 项目提出的相关路线。节点和连线可点选查看，主题分图可在左上角切换。','The atlas shows materials and processes in space systems alongside routes proposed by iGEM projects. Nodes and connections open their details; the topic menu switches diagrams.')}</p><div class="welcome-actions"><button class="control primary" data-start-reading>${L('阅读操作指引','Reading guide')}<span>↗</span></button><button class="control" data-theme-jump="water" data-target-node="wrs">${L('水循环分图','Water cycle diagram')}<span>01 →</span></button><button class="control" data-theme-jump="bioreactor">${L('生物反应器分图','Bioreactor diagram')}<span>02 →</span></button></div><div class="welcome-stats"><div><strong>${p.teams.length}</strong><small>${L('已绘入队伍','Teams with routes')}</small></div><div><strong>${b.themes.length}</strong><small>${L('主题分图','Theme diagrams')}</small></div></div><h3>${L('连线图例','Connection legend')}</h3><div class="line-key"><i></i>${L('基础系统的物质流','Baseline material flow')}</div><div class="line-key project"><i></i>${L('团队提出的路线','Proposed team routes')}</div><div class="line-key dotted"><i></i>${L('工艺之间的联系','Links between processes')}</div><p class="tiny">${L('金色角标标注工艺改良；Future 表示项目设想中的太空应用。图谱为定性描述。','Gold badges mark process improvements. Future denotes a proposed space application. The atlas is qualitative.')}</p><h3>${L('图中的边界','Boundaries in the atlas')}</h3>${boundaryLegend()}<button class="control" data-page="about">About</button>`)}
function boundaryLegend(){return [[L('宇航员与乘员','Crew'),'#e6edf2'],[L('从地球补给','Supplied from Earth'),'#e0efe9'],[L('返回地球','Return to Earth'),'#e4edf9'],[L('废弃物再入处置','Waste disposal by reentry'),'#f5e5dc'],[L('排放到舱外','Discharge to space'),'#ede9e5']].map(([label,color])=>`<div class="corner-key"><span class="corner-swatch" style="background:${color}"></span>${label}</div>`).join('')}
function sourcesHTML(ids){const map=allSources();return [...new Set(ids)].map(id=>{const s=map[id];if(!s)return '';const u=s.display_url||s.review_url||s.url;return `<div class="source-link">${u?link(u,s.title||id):esc(s.title||id)}${!u?`<small>${L('团队提供的项目资料，可联系维护者获取相关说明。','Team-supplied project material; contact the maintainers for details.')}</small>`:''}<small>${esc(s.publisher||L('团队项目资料','Team project materials'))}</small></div>`}).join('')||`<p class="tiny">${L('这项内容来自团队提供的项目资料。','This item is described in team-supplied project materials.')}</p>`}
function nodeDetail(id){const n=scene.model.nodes[id];if(!n)return;const t=n.owner&&owners()[n.owner],v=visibility(),incoming=v.edges.filter(e=>e.target===id),outgoing=v.edges.filter(e=>e.source===id),sources=[...(n.source_ids||[]),...(t?.source_ids||[]),...incoming.flatMap(e=>e.source_ids||[]),...outgoing.flatMap(e=>e.source_ids||[])];
 const relList=(es,inward)=>es.map(e=>{const other=scene.model.nodes[inward?e.source:e.target];return `<li><button class="control tiny" data-node-jump="${esc(other.logical_id)}">${esc(tx(other.label))}</button> <span>${esc(tx(e.label))}</span></li>`}).join('');
 const desc=n.narrative?tx(n.narrative):(lang==='zh'?n.description:n.description_en)||t&&tx(t.narrative)||'';
 detail(`<div class="eyebrow">${esc(tx(names[n.theme]||n.theme))}</div><h2>${esc(tx(n.label))}</h2>${n.future?'<span class="pill">Future</span>':''}${n.demonstration?`<span class="pill">${L('示范路线','Demonstration')}</span>`:''}${drafts[n.owner]?`<span class="pill draft-pill">${L('本机资料','Local contribution')}</span>`:''}<p>${esc(desc)}</p>${t?`<p class="tiny">${t.year} · ${esc(t.name)}</p><div class="actions"><button class="control" data-team-page="${esc(t.id)}">${L('队伍介绍','Team page')}</button><button class="control" data-team-focus="${esc(t.id)}">${L('只看本队','Focus team')}</button></div>`:''}${n.target_view?`<button class="control" style="margin-top:10px" data-theme-jump="${esc(n.target_view)}" data-target-node="${esc(n.logical_id)}">${L('进入主题图','Open theme')}</button>`:''}${incoming.length?`<h3>${L('上游联系','Upstream connections')}</h3><ul class="flow-list">${relList(incoming,true)}</ul>`:''}${outgoing.length?`<h3>${L('下游联系','Downstream connections')}</h3><ul class="flow-list">${relList(outgoing,false)}</ul>`:''}<h3>${L('来源','Sources')}</h3>${sourcesHTML(sources)}<p class="tiny">${link(DATA.config.contact.url,L('补充或更正这项介绍','Suggest an addition or correction'))}</p>`);
}
function edgeDetail(ids){const es=ids.map(id=>scene.model.edges.find(e=>e.id===id)).filter(Boolean),first=es[0];if(!first)return;picked={kind:'edge',ids};detail(`<div class="eyebrow">${esc(tx(categoryNames[first.category]))}</div><h2>${esc(tx(scene.model.nodes[first.source].label))}<br>→ ${esc(tx(scene.model.nodes[first.target].label))}</h2>${es.map(e=>`<p>${esc(tx(e.label))}</p>${e.scope?`<p>${esc(lang==='zh'?e.scope:e.scope_en||e.scope)}</p>`:''}${e.owner?`<button class="control tiny" data-team-page="${esc(e.owner)}">${esc(owners()[e.owner].name)}</button>`:''}`).join('')}<h3>${L('来源','Sources')}</h3>${sourcesHTML(es.flatMap(e=>e.source_ids||[]))}`)}
function teamCore(id){const t=owners()[id];if(!t)return null;const effects=p.enhancements.filter(e=>e.owner===id&&allNodes()[e.source]?.owner===id);return effects[0]?.source||t.chains.find(c=>!c.demonstration&&c.theme===t.primary_theme)?.step_ids[0]||t.chains.find(c=>!c.demonstration)?.step_ids[0]||t.chains[0]?.step_ids[0]}
function selectionCore(){return selected.size===1?teamCore([...selected][0]):null}
async function focusTeam(id){if(!owners()[id]){openEditor(id);return}selected=new Set([id]);teamScope=id;view='overview';picked=null;await showGraph(teamCore(id));const t=owners()[id];detail(`<div class="eyebrow">${t.year} · iGEM</div><h2>${esc(t.name)}</h2><p>${esc(tx(t.narrative||{zh:t.description,en:t.description_en}))}</p><div class="actions"><button class="control" data-team-page="${esc(id)}">${L('队伍介绍','Team page')}</button><button class="control" data-theme-jump="${t.primary_theme}">${L('展开主题步骤','Explore process steps')}</button></div><h3>${L('来源','Sources')}</h3>${sourcesHTML(t.source_ids)}`)}
function setNav(){document.querySelectorAll('.nav [data-page]').forEach(e=>e.classList.toggle('active',e.dataset.page===pageName))}
function content(name,html){document.body.classList.remove('graph-active');window.AtlasExperience?.stopFlow();pageName=name;setNav();$('#graph-page').hidden=true;$('#content-page').hidden=false;$('#content-page').innerHTML=(embedded?`<button class="control" style="margin-bottom:20px" data-page="graph">${L('← 返回图谱','← Back to atlas')}</button>`:'')+html;window.scrollTo(0,0)}
function showPage(name){if(name==='graph'){showGraph();return}if(name==='contribute'){openEditor();return}if(name==='teams'){teamDirectory();return}if(name==='references'){referencePage();return}if(name==='about'){aboutPage();return}if(name==='embed'){embedPage();return}}
function teamDirectory(){const roster=[...DATA.roster.teams,...p.teams.filter(t=>!DATA.roster.teams.some(r=>r.id===t.id)).map(t=>({...t,country:L('本机资料','Local contribution'),city:''}))].filter(t=>t.year===rosterYear);const cards=roster.map(r=>{const t=owners()[r.id];return `<article class="team-card"><div class="eyebrow">${r.year} · ${esc(r.country)} / ${esc(r.city)}</div><h3>${esc(r.name)}</h3><span class="pill">${t?L('已纳入图谱','Integrated'):L('等待增补','Awaiting additions')}</span><p>${t?esc(tx(t.role)):L('从自己的项目出发，补充与现有物质和工艺的联系。','Add your project and its links to existing materials and processes.')}</p><div class="actions"><button class="control" data-team-page="${esc(r.id)}">${L('队伍页面','Team page')}</button>${t?`<button class="control" data-team-focus="${esc(r.id)}">${L('聚焦路线','Focus route')}</button>`:`<button class="control editor-action" data-edit-team="${esc(r.id)}">${L('填写路线','Add route')}</button>`}</div></article>`}).join('');
 content('teams',`<div class="eyebrow">THE SPACE VILLAGE</div><h1>${L('不断生长的队伍目录','A growing directory of teams')}</h1><p class="intro">${L('2024—2025 年的 21 支队伍与 2026 年的 17 支队伍，共同构成 Space Village 的项目目录。已加入的路线可以直接聚焦查看；新路线从填写团队资料开始。','The directory brings together 21 teams from 2024–2025 and 17 teams from 2026. Explore existing routes, or contribute a new team route.')}</p><div class="year-tabs">${[2024,2025,2026].map(y=>`<button data-roster-year="${y}" class="${y===rosterYear?'active':''}">${y} · ${DATA.roster.teams.filter(t=>t.year===y).length}</button>`).join('')}</div><div class="team-grid">${cards}</div><h2>${L('未来展望','Future outlook')}</h2><p>${L('尚未进入名录的队伍属于未来拓展范围，不计入当前统计。已列名但尚无图谱路线的队伍标记为等待增补。','Teams outside the directory are future additions and are not counted here. Listed teams without graph routes are marked Awaiting additions.')}</p><p class="tiny">${L('名录来源：','Roster source: ')}${link(DATA.roster.source,'iGEM Team List')} · ${DATA.roster.as_of}</p>`);
}
async function teamPage(id){const r=DATA.roster.teams.find(t=>t.id===id),t=owners()[id];if(!r&&!t){content('teams',`<h1>${L('未来展望','Future outlook')}</h1><p>${L('该队伍尚未进入当前名录，不计入已收录队伍和路线统计。','This team is not in the current directory and is not counted among listed teams or modeled routes.')}</p>`);return;}const name=t?.name||r.name,year=t?.year||r.year;content('teams',`<div class="eyebrow">${year} · SPACE VILLAGE</div><h1>${esc(name)}</h1><span class="pill">${t?L('已纳入图谱','Integrated'):L('等待增补','Awaiting additions')}</span><p class="intro">${t?esc(tx(t.narrative||{zh:t.description,en:t.description_en})):L('这支队伍已列入 Space Village 名录。项目路线可通过团队表单加入图谱。','This team is listed in Space Village. Its project route can be added through the contribution form.')}</p><div class="actions">${t?`<button class="control primary" data-team-focus="${esc(id)}">${L('在图谱中聚焦本队','Focus this team in the atlas')}</button>`:''}<button class="control editor-action" data-edit-team="${esc(id)}">${t?L('编辑本队资料','Edit team contribution'):L('填写本队路线','Contribute team route')}</button>${link(t?.url||r.wiki||r.url,L('项目主页 ↗','Project website ↗'))}${t?`<button class="control" data-export-team="${esc(id)}">${L('导出队伍资料','Export team bundle')}</button><button class="control editor-action" data-export-description="${esc(id)}">${L('导出队伍描述','Export team description')}</button>`:''}</div>${t?`<div class="rule"></div><h2>${L('路线与工艺','Routes and processes')}</h2>${t.chains.map(c=>`<article class="reference"><span class="pill">${esc(tx(names[c.theme]))}</span>${c.demonstration?`<span class="pill">${L('示范','Demonstration')}</span>`:''}<h3>${esc(tx(c.label))}</h3><p>${c.step_ids.map(k=>esc(tx(allNodes()[k].label))).join(' · ')}</p><button class="control tiny" data-theme-jump="${esc(c.theme)}" data-select-team="${esc(id)}">${L('打开主题图','Open theme diagram')}</button></article>`).join('')}<h2>${L('来源','Sources')}</h2>${sourcesHTML(t.source_ids)}`:`<p class="empty-note">${L('目录保留队伍身份，图中的连接由具体项目资料填写。','The directory preserves the team identity; graph connections are added from project materials.')}</p>`}${drafts[id]?`<div class="rule"></div><p class="tiny">${L('当前显示本机保存的资料。导出文件可交给维护者合并。','This page shows a locally saved contribution. Export it for inclusion by the maintainers.')}</p><button class="control danger editor-action" data-remove-draft="${esc(id)}">${L('移除本机修改','Remove local changes')}</button>`:''}`);}
function referencePage(filter=''){const teamSources=p.sources,baseSources=b.sources;const text=(s)=>tx(s.description||{zh:'',en:''})||s.publisher||'';const render=s=>`<article class="reference"><div class="eyebrow">${esc(s.publisher||L('团队项目资料','Team project materials'))}</div><h3>${esc(s.title)}</h3><p>${esc(text(s))}</p>${s.display_url||s.review_url||s.url?link(s.display_url||s.review_url||s.url,L('阅读原始资料 ↗','Read source ↗')):link(DATA.config.contact.url,L('联系维护者了解团队提供的资料','Contact maintainers about team-supplied material'))}</article>`;const matches=s=>`${s.title} ${text(s)}`.toLowerCase().includes(filter.toLowerCase());content('references',`<div class="eyebrow">REFERENCES & CONTEXT</div><h1>${L('每一条介绍，都能继续往下读','Follow each description to its sources')}</h1><p class="intro">${L('项目介绍依据团队 Wiki 与团队提供的资料整理，基础系统参考航天机构和相关研究。这里保留原始来源，方便读者了解项目本身。','Project descriptions draw on team Wikis and team-supplied materials. Baseline systems refer to space agencies and relevant research. Original sources are retained for further reading.')}</p><input id="reference-filter" class="control" type="search" value="${esc(filter)}" placeholder="${L('搜索队名、技术或来源','Search team, technology or source')}"><h2>${L('团队项目','Team projects')}</h2><div class="sources-list">${teamSources.filter(matches).map(render).join('')}</div><h2>${L('基础系统','Baseline systems')}</h2><div class="sources-list">${baseSources.filter(matches).map(render).join('')}</div>`)}
function aboutPage(){content('about',`<div class="eyebrow">ABOUT THE ATLAS</div><div class="about-grid"><div><h1>${L('把不同项目，放进同一幅太空全景','Different projects, one space panorama')}</h1><p class="quote">${L('从地球的补给，到太空中的再利用。','From supplies on Earth to reuse in space.')}</p><p>${esc(tx(DATA.config.about))}</p><h2>${L('如何理解这些连接','Connection legend')}</h2><p>${L('图谱展示物质和工艺可能形成的联系。团队路线与共享工艺之间的连接，用于呈现项目在整体系统中的位置。不同队伍可以研究同一个节点，也可以为同一工艺提供不同的改良模块。','Connections describe how materials and processes may relate. Links between team routes and shared processes locate projects within the larger system. Several teams may study the same node or contribute different improvements to one process.')}</p><p>${L('这里采用定性表达：不计算物质流量、不比较量化性能。Future 表示项目设想中的太空应用，路线按项目目标实现后的情景展开。','The atlas is qualitative: it does not calculate material flow rates or compare quantitative performance. Future denotes a project’s space application, with routes shown in a project-goal scenario.')}</p><h2>${L('补充与更正','Additions and corrections')}</h2><p>${L('人工整理可能有所错漏。如果项目介绍、物质连接或队伍信息需要修改，欢迎联系：','Manual compilation may contain errors or omissions. For corrections to project descriptions, material connections or team information, contact:')}</p><p>${contactLink()}</p><p>${L('团队可以通过表单填写路线，导出资料文件，并发送给维护者。','Teams can fill in a route, export the contribution file and send it to the maintainers.')}</p><button class="control primary editor-action" data-page="contribute">${L('填写团队路线','Contribute a team route')}</button></div><aside class="about-aside"><div class="stat-line">21 <span>${L('2024—2025 年 Space Village 队伍','Space Village teams in 2024–2025')}</span></div><div class="stat-line">17 <span>${L('2026 年 Space Village 队伍','Space Village teams in 2026')}</span></div><div class="rule"></div><h2>${L('地球与太空的边界','Earth and space boundaries')}</h2>${boundaryLegend()}<p class="tiny">${L('地球补给、返回地球与废弃物处置分别标注，说明物资从哪里进入，又从哪里离开。','Earth supply, return transport and waste disposal are marked separately, showing where materials enter and leave.')}</p><div class="rule"></div><p class="tiny">${L('名录来源','Roster source')}：${link(DATA.roster.source,'iGEM Team List')}<br>${DATA.roster.as_of}<br>Space Material Atlas · ${DATA.config.version}</p></aside></div>`)}
function embedURL(team=''){const url=new URL(DATA.config.canonical_url||location.href);url.hash='';url.search='';url.searchParams.set('embed','1');url.searchParams.set('mode','display');url.searchParams.set('lang',lang);if(team){url.searchParams.set('team',team);url.searchParams.set('focusTeam','1')}return url.href}
function embedPage(){const id=selected.size===1?[...selected][0]:'',url=embedURL(id),snippet=`<iframe\n  src="${url}"\n  title="Space Material Atlas"\n  width="100%" height="680"\n  style="border:0" loading="lazy"\n  allow="fullscreen">\n</iframe>`;content('embed',`<div class="eyebrow">EMBED THE ATLAS</div><h1>${L('让图谱出现在你的团队页面','Bring the atlas to your team page')}</h1><p class="intro">${L('同一个 HTML 组件可以嵌入不同网页。链接参数可指定队伍、主题和节点；组件保留缩放、介绍和来源。','The same HTML component can appear on different websites. Link parameters select a team, theme or node while preserving zoom, descriptions and sources.')}</p><div class="field" style="max-width:440px"><label>${L('初始队伍','Initial team')}</label><select id="embed-team" class="control"><option value="">${L('基础系统','Baseline')}</option>${p.teams.map(t=>`<option value="${t.id}" ${t.id===id?'selected':''}>${t.year} · ${esc(t.name)}</option>`).join('')}</select></div><label class="tiny"><input id="embed-full-header" type="checkbox"> ${L('保留完整导航（展示模式，仅隐藏编辑入口）','Keep full navigation (display mode, editing hidden)')}</label><p class="tiny">${L('发布后使用托管地址引用该组件；本地演示页用于测试嵌入效果。','After publishing, use the hosted URL to reference this component. The local demonstration page tests embedding.')}</p><pre class="codebox" id="embed-code">${esc(snippet)}</pre><div class="actions"><button class="control" id="copy-embed">${L('复制代码','Copy code')}</button><button class="control" id="download-embed">${L('下载示例网页','Download example page')}</button><a class="control" href="iframe-demo.html" target="_blank" rel="noopener">${L('打开嵌入演示 ↗','Open embedding demo ↗')}</a></div><h2>${L('与宿主页面联动','Control from the host page')}</h2><p>${L('宿主可以切换队伍、打开主题或聚焦节点。组件只接受指定宿主来源的消息；消息协议和示例随组件提供。','The host can select teams, open themes or focus nodes. The component accepts messages only from its designated parent origin. The message protocol and examples accompany the component.')}</p><pre class="codebox">${esc(`frame.contentWindow.postMessage({\n  type: "space-atlas:focus-node",\n  version: 1, id: "space_bioreactor"\n}, new URL(frame.src).origin);`)}</pre>`)}

/* Contribution form: every connection reuses a catalog ID or an owned node ID. */
function field(label,bind,value,type='text',extra=''){return `<label class="field ${type==='textarea'?'full':''}"><span>${label}</span>${type==='textarea'?`<textarea data-bind="${bind}" ${extra}>${esc(value||'')}</textarea>`:`<input type="${type}" data-bind="${bind}" value="${esc(value??'')}" ${extra}>`}</label>`}
function nodeChoice(id){const n=[...(editorBundle?.nodes||[]),...b.nodes,...p.nodes].find(n=>n.id===id);return n?`${tx(n.label)} [${id}]`:id||''}
function resolveChoice(value){const match=value.match(/\[([^\]]+)\]\s*$/);return match?match[1]:value.trim()}
function routeOptions(id,allowEmpty=false){return (allowEmpty?`<option value="">${L('平台或独立材料','Platform or separate material')}</option>`:'')+editorBundle.team.chains.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(tx(c.label))}</option>`).join('')}
function editorCatalog(){const map=new Map([...b.nodes,...p.nodes.filter(n=>n.owner!==editorBundle.team.id),...editorBundle.nodes].map(n=>[n.id,n]));return `<datalist id="node-catalog">${[...map.values()].sort((a,b)=>tx(a.label).localeCompare(tx(b.label))).map(n=>`<option value="${esc(nodeChoice(n.id))}">${esc(tx(names[n.theme]||n.theme))}${n.owner?' · '+(owners()[n.owner]?.name||editorBundle.team.name):''}</option>`).join('')}</datalist>`}
function openEditor(id=null){if(readOnly){toast(L('嵌入组件为阅读模式，请在完整图谱中填写路线。','Open the full atlas to contribute a route.'));return}const roster=id&&DATA.roster.teams.find(t=>t.id===id);editorOriginalID=id&&owners()[id]?id:null;editorBundle=editorOriginalID?C.teamBundle(p,id):C.makeBlank({id:roster?.id,year:roster?.year||2026,name:roster?.name||'',wiki:roster?.wiki||roster?.url||''});editorSeedID=editorBundle.team.id;editorRelations=[...editorBundle.edges,...editorBundle.dependencies,...editorBundle.enhancements];renderEditor();window.AtlasExperience?.editorEntered()}
function renderEditor(){const t=editorBundle.team;content('contribute',`<div class="eyebrow">CONTRIBUTE A ROUTE</div><h1>${editorOriginalID?L('让自己的路线更完整','Refine your team’s route'):L('把你的项目，接入这幅图','Connect your project to the atlas')}</h1><p class="intro">${L('优先选择图谱中已有的物质与工艺。添加自己的步骤、分支和连接说明，预览后保存或导出。','Reuse existing materials and processes first. Add your steps, branches and connection descriptions, then preview, save or export.')}</p><div class="actions"><a class="control editor-action" href="proofreader.html" target="_blank" rel="noopener">${L('打开 JSON 文本校对台','Open JSON proofreader')}</a><button class="control" data-import-bundle>${L('导入已有资料','Import a bundle')}</button><button class="control" type="button" data-start-editor>${L('编辑指引','Editing guide')}</button><button class="control" id="load-example">${L('试填一个示例','Try an example')}</button></div><div class="editor-layout"><form class="editor-form" id="team-form" novalidate><fieldset><legend>01 · ${L('队伍与项目','Team and project')}</legend><div class="field-grid">${field(L('年份','Year'),'team.year',t.year,'number',editorOriginalID?'readonly':'min="2004" max="2100"')}${field(L('队伍标识（年份-ID）','Team ID (year-ID)'),'team.id',t.id,'text',editorOriginalID?'readonly':'')}${field(L('队名','Team name'),'team.name',t.name)}${field(L('项目主页','Project URL'),'team.url',t.url,'url')}${field(L('图中简短名称','Short graph label'),'team.role.zh',t.role.zh)}${field(L('英文短名（可选）','English short label (optional)'),'team.role.en',t.role.en)}<label class="field"><span>${L('主要主题','Main theme')}</span><select data-bind="team.primary_theme">${themeOptions(t.primary_theme)}</select></label>${field(L('项目介绍：直接描述做了什么','Project description: describe the route'),'team.description',t.description,'textarea')}${field(L('英文介绍（可选）','English description (optional)'),'team.description_en',t.description_en,'textarea')}</div></fieldset><fieldset><legend>02 · ${L('路线与示范','Routes and demonstrations')}</legend>${t.chains.map((c,i)=>`<div class="editor-row"><div class="row-head"><b>${L('路线','Route')} ${i+1}</b>${t.chains.length>1?`<button type="button" data-delete-route="${i}">${L('删除路线','Remove route')}</button>`:''}</div><div class="field-grid">${field(L('路线名称','Route name'),`team.chains.${i}.label.zh`,c.label.zh)}${field(L('英文名称（可选）','English name (optional)'),`team.chains.${i}.label.en`,c.label.en)}<label class="field"><span>${L('主题','Theme')}</span><select data-bind="team.chains.${i}.theme">${themeOptions(c.theme)}</select></label><label class="tiny"><input type="checkbox" data-bind="team.chains.${i}.demonstration" ${c.demonstration?'checked':''}> ${L('示范路线：在主题图展开','Demonstration: shown in theme diagrams')}</label></div></div>`).join('')}<button type="button" class="control" data-add-route>+ ${L('增加一条路线','Add route')}</button></fieldset><fieldset><legend>03 · ${L('本队步骤与新节点','Your steps and new nodes')}</legend><p class="tiny">${L('已有节点无需重建，在下一节直接选择。这里填写本队新增的工艺、材料或状态。','Do not recreate existing nodes; select them in the next section. Add only your processes, materials or states here.')}</p>${editorBundle.nodes.map((n,i)=>`<div class="editor-row"><div class="row-head"><b>${esc(n.id)}</b><button type="button" data-delete-node="${i}">${L('删除','Remove')}</button></div><div class="field-grid">${field(L('名称','Name'),`nodes.${i}.label.zh`,n.label.zh)}${field(L('英文名称（可选）','English name (optional)'),`nodes.${i}.label.en`,n.label.en)}<label class="field"><span>${L('类型','Type')}</span><select data-bind="nodes.${i}.kind">${[['process',L('工艺步骤','Process')],['material',L('物质','Material')],['state',L('状态','State')],['information',L('信息','Information')],['energy',L('能量','Energy')],['resource',L('资源','Resource')]].map(([v,l])=>`<option value="${v}" ${n.kind===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>${L('所属路线','Route')}</span><select data-bind="nodes.${i}.route">${routeOptions(n.route,true)}</select></label>${field(L('介绍或作用','Description or role'),`nodes.${i}.description`,n.description,'textarea')}${field(L('英文介绍（可选）','English description (optional)'),`nodes.${i}.description_en`,n.description_en,'textarea')}</div></div>`).join('')}<button type="button" class="control" data-add-node>+ ${L('增加步骤 / 节点','Add step / node')}</button></fieldset><fieldset><legend>04 · ${L('连接与分支','Connections and branches')}</legend>${editorRelations.map((e,i)=>`<div class="editor-row"><div class="row-head"><b>${L('连接','Connection')} ${i+1}</b><button type="button" data-delete-edge="${i}">${L('删除','Remove')}</button></div><div class="connection-grid"><label class="field"><span>${L('上游：输入名称搜索已有节点','Upstream: search an existing node')}</span><input list="node-catalog" data-endpoint="${i}:source" value="${esc(nodeChoice(e.source))}" placeholder="${L('例如：可用水','e.g. usable water')}"></label><span class="arrow">→</span><label class="field"><span>${L('下游：已有节点或本队步骤','Downstream: existing node or your step')}</span><input list="node-catalog" data-endpoint="${i}:target" value="${esc(nodeChoice(e.target))}"></label></div><div class="field-grid" style="margin-top:12px"><label class="field"><span>${L('联系类型','Connection type')}</span><select data-bind="relations.${i}.category">${Object.entries(categoryNames).map(([v,l])=>`<option value="${v}" ${e.category===v?'selected':''}>${esc(tx(l))}</option>`).join('')}</select></label><label class="field"><span>${L('所属路线','Route')}</span><select data-bind="relations.${i}.route">${routeOptions(e.route,true)}</select></label>${field(L('标注：流动的物质或工艺作用','Annotation: material or process role'),`relations.${i}.label.zh`,e.label?.zh)}${field(L('英文标注（可选）','English annotation (optional)'),`relations.${i}.label.en`,e.label?.en)}${field(L('补充说明；改良请写作用机制','Notes; describe the mechanism for improvements'),`relations.${i}.scope`,e.scope||'','textarea')}${field(L('英文补充说明（可选）','English notes (optional)'),`relations.${i}.scope_en`,e.scope_en||'','textarea')}<label class="field"><span>${L('这条连接的来源','Source for this connection')}</span><select data-bind="relations.${i}.source_ids.0">${editorBundle.sources.map(s=>`<option value="${esc(s.id)}" ${e.source_ids?.[0]===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></label></div></div>`).join('')}<button type="button" class="control" data-add-edge>+ ${L('增加连接 / 分支','Add connection / branch')}</button></fieldset><fieldset><legend>05 · ${L('项目来源','Project sources')}</legend>${editorBundle.sources.map((s,i)=>`<div class="editor-row"><div class="field-grid">${field(L('资料标题','Source title'),`sources.${i}.title`,s.title)}${field(L('原始链接','Source URL'),`sources.${i}.url`,s.url,'url')}${field(L('这份资料介绍了什么','What this source describes'),`sources.${i}.description.zh`,s.description?.zh||'','textarea')}${field(L('英文资料说明（可选）','English source description (optional)'),`sources.${i}.description.en`,s.description?.en||'','textarea')}</div></div>`).join('')}<button type="button" class="control" data-add-source>+ ${L('增加来源','Add source')}</button></fieldset><div id="form-errors" class="errors" hidden role="alert"></div><div class="save-bar"><button type="button" id="preview-route" class="control">${L('预览路线','Preview route')}</button><button type="button" id="save-team" class="control primary">${L('保存到本机图谱','Save to local atlas')}</button><button type="button" class="control" data-export-description="editor">${L('导出队伍描述','Export team description')}</button><button type="button" id="export-form" class="control">${L('导出队伍资料','Export team bundle')}</button></div><p class="notice" id="form-notice"></p></form><aside class="editor-note"><h3>${L('沿用图中已有的点位','Build on existing nodes')}</h3><ol><li>${L('输入节点名称，从建议中选择。','Type a node name and select a suggestion.')}</li><li>${L('工艺步骤之间可以连接，也可以从任意一步分出支路。','Connect steps or branch from any step.')}</li><li>${L('改良关系指向被改良的工艺，自动形成金色角标。','Improvement links point to the affected process and create a gold badge.')}</li><li>${L('示范路线与平台作用分别填写。','Keep demonstrations separate from the platform role.')}</li></ol><p>${L('表单只做定性描述，不要求流量、产率或性能数值。','Describe the route qualitatively; no flow rates, yields or performance values are required.')}</p><p>${L('保存仅影响当前浏览器。导出后可将 JSON 文件发送给维护者，加入公共版本。','Saving affects this browser only. Export the JSON file and send it to the maintainers for the shared version.')}</p>${contactLink()}<div id="route-preview" class="editor-preview"></div><div class="rule"></div><p>${L('新增加的数据可能需要重新排版；日常开关队伍保持位置。','New content may trigger layout changes; ordinary team toggles preserve positions.')}</p></aside></div>${editorCatalog()}`);}
function setBinding(path,value){const parts=path.split('.');let obj=parts[0]==='relations'?{relations:editorRelations}:editorBundle;for(let i=0;i<parts.length-1;i++){obj[parts[i]]??={};obj=obj[parts[i]]}obj[parts.at(-1)]=value}
function freshID(prefix,items){let i=0;while(items.some(x=>x.id===`${prefix}:${i}`))i++;return `${prefix}:${i}`}
function normalizedBundle(){const bundle=C.clone(editorBundle),t=bundle.team,old=editorSeedID||editorOriginalID||t.id,id=t.id.trim();if(old!==id){const replace=x=>typeof x==='string'?x.replaceAll(old,id):x;function walk(x){if(Array.isArray(x))return x.map(walk);if(x&&typeof x==='object')return Object.fromEntries(Object.entries(x).map(([k,v])=>[k,walk(v)]));return replace(x)}Object.assign(bundle,walk(bundle))}
 const team=bundle.team;team.year=Number(team.year);team.name=team.name.trim();team.role=C.bi(team.role.zh,team.role.en);team.description_en=team.description_en||team.description;team.narrative=C.bi(team.description,team.description_en);team.themes=[...new Set([team.primary_theme,...team.chains.map(c=>c.theme)])];team.source_ids=bundle.sources.map(s=>s.id);
 bundle.edges=[];bundle.dependencies=[];bundle.enhancements=[];
 for(const n of bundle.nodes){n.owner=team.id;n.layer='project';n.future=true;n.label=C.bi(n.label.zh,n.label.en);n.description_en=n.description_en||n.description;n.narrative=C.bi(n.description,n.description_en);n.theme=team.chains.find(c=>c.id===n.route)?.theme||team.primary_theme;n.source_ids=n.source_ids?.length?n.source_ids:team.source_ids}
 for(const s of bundle.sources){s.description=C.bi(s.description?.zh||'',s.description?.en||s.description?.zh||'');s.kind=s.kind||'team_supplied'}
 for(const original of editorRelations){const e=C.clone(original);if(old!==id){for(const key of ['id','owner','source','target','route'])if(e[key])e[key]=e[key].replaceAll(old,id);e.source_ids=(e.source_ids||[]).map(x=>x.replaceAll(old,id))}e.owner=team.id;e.source=resolveChoice(e.source||'');e.target=resolveChoice(e.target||'');e.label=C.bi(e.label?.zh,e.label?.en);e.route=e.route||null;e.theme=team.chains.find(c=>c.id===e.route)?.theme||team.primary_theme;e.demonstration=!!team.chains.find(c=>c.id===e.route)?.demonstration;e.layer='project';e.scenario='assumed_success';e.source_ids=e.source_ids?.filter(Boolean).length?e.source_ids:[team.source_ids[0]];
  if(e.category==='enhancement'){e.kind=e.kind||'process_improvement';e.scope_en=e.scope_en||e.scope;e.measured_gain=null;bundle.enhancements.push(e)}else if(e.category==='dependency'){e.basis='team_supplied';bundle.dependencies.push(e)}else bundle.edges.push(e);
 }
 for(const c of team.chains){c.label=C.bi(c.label.zh,c.label.en);c.step_ids=bundle.nodes.filter(n=>n.route===c.id).map(n=>n.id);c.edge_ids=bundle.edges.filter(e=>e.route===c.id).map(e=>e.id);c.dependencies=bundle.dependencies.filter(e=>e.route===c.id).map(e=>e.target);delete c.note}
 return bundle;
}
function checkedForm(){const bundle=normalizedBundle(),errors=C.validateBundle(b,p,bundle);if(!bundle.edges.length&&!bundle.dependencies.length&&!bundle.enhancements.length)errors.push(L('请至少填写一条连接。','Add at least one connection.'));$('#form-errors').hidden=!errors.length;$('#form-errors').textContent=errors.join('\n');if(errors.length){$('#form-errors').scrollIntoView({block:'center'});return null}return bundle}
async function previewForm(){const bundle=checkedForm();if(!bundle)return;const nodes=Object.fromEntries([...b.nodes,...p.nodes.filter(n=>n.owner!==bundle.team.id),...bundle.nodes].map(n=>[n.id,n])),edges=[...bundle.edges,...bundle.dependencies,...bundle.enhancements],used=new Set(edges.flatMap(e=>[e.source,e.target])),model={view:'contribution',nodes:Object.fromEntries([...used].map(id=>[id,{...nodes[id],logical_id:id,display_theme:nodes[id].theme,remote:!nodes[id].owner}])),edges};$('#route-preview').textContent=L('正在排布…','Preparing preview…');try{const geometry=await R.layout(model,lang),temp=C.upsert(b,p,bundle);$('#route-preview').innerHTML=R.render(model,geometry,b,temp,lang)}catch(e){$('#form-errors').hidden=false;$('#form-errors').textContent=e.message}}
function addExample(){editorBundle=C.makeBlank({id:'2026-example',year:2026,name:L('示例队伍','Example Team'),wiki:'https://teams.igem.org/list',theme:'water'});editorOriginalID=null;editorSeedID=editorBundle.team.id;const t=editorBundle.team;t.role=C.bi('营养盐回收示例','Nutrient recovery example');t.description=L('示例展示如何把已有废物节点通过本队工艺连接到营养盐。','This example connects an existing waste node to nutrient salts through a team process.');const route=t.chains[0];editorBundle.nodes=[{id:t.id+':step:0',owner:t.id,route:route.id,theme:'water',kind:'process',layer:'project',future:true,label:C.bi('示例回收工艺','Example recovery process'),description:L('填写本队实际提出的转化过程。','Describe the process proposed by the team.')}];editorRelations=[['f_waste',editorBundle.nodes[0].id,'含营养元素的废物','Nutrient-bearing waste'],[editorBundle.nodes[0].id,'f_salts','回收培养营养盐','Recovered cultivation salts']].map(([source,target,zh,en],i)=>({id:t.id+':edge:'+i,owner:t.id,route:route.id,source,target,category:'material',label:C.bi(zh,en),source_ids:t.source_ids}));renderEditor();$('#form-notice').textContent=L('这是填表示例，不代表已收录项目；请替换为本队资料后保存。','This is a form example, not a listed project. Replace it with your team’s material before saving.')}

/* Navigation, graph interaction and contribution actions. */
document.addEventListener('click',async e=>{const button=e.target.closest('button,a,summary');if(!button)return;
 if(button.dataset.page){e.preventDefault();showPage(button.dataset.page);return}
 if(button.hasAttribute('data-close-detail')){$('#graph-shell').classList.add('closed');return}
 if(button.dataset.teamPage){teamPage(button.dataset.teamPage);return}if(button.dataset.teamFocus){await focusTeam(button.dataset.teamFocus);return}if(button.dataset.editTeam){openEditor(button.dataset.editTeam);return}
 if(button.dataset.exportDescription){await exportTeamReport(button.dataset.exportDescription,button);return}
 if(button.dataset.exportTeam){download(button.dataset.exportTeam+'.json',JSON.stringify(C.teamBundle(p,button.dataset.exportTeam),null,2));return}
 if(button.dataset.themeJump){if(button.dataset.selectTeam){selected=new Set([button.dataset.selectTeam]);teamScope=button.dataset.selectTeam}view=button.dataset.themeJump;await showGraph(button.dataset.targetNode||null);return}
 if(button.dataset.nodeJump){await focusNode(button.dataset.nodeJump);return}if(button.dataset.rosterYear){rosterYear=Number(button.dataset.rosterYear);teamDirectory();return}
 if(button.dataset.removeDraft){try{const nextDrafts={...drafts};delete nextDrafts[button.dataset.removeDraft];let next=C.clone(DATA.projects);for(const bundle of Object.values(nextDrafts))next=C.upsert(b,next,bundle);drafts=nextDrafts;p=next;selected=new Set([...selected].filter(id=>owners()[id]));revision++;sceneCache={};persistDrafts();teamChecks();if(owners()[button.dataset.removeDraft]||DATA.roster.teams.some(t=>t.id===button.dataset.removeDraft))teamPage(button.dataset.removeDraft);else teamDirectory()}catch(err){toast(err.message)}return}
 if(button.hasAttribute('data-import-bundle')){$('#bundle-import').click();return}
 if(button.hasAttribute('data-add-node')){const t=editorBundle.team;editorBundle.nodes.push({id:freshID(t.id+':node',editorBundle.nodes),owner:t.id,route:t.chains[0].id,kind:'process',theme:t.primary_theme,layer:'project',future:true,label:C.bi('',''),description:''});renderEditor();return}
 if(button.hasAttribute('data-add-edge')){const t=editorBundle.team;editorRelations.push({id:freshID(t.id+':connection',editorRelations),owner:t.id,route:t.chains[0].id,source:'',target:'',category:'material',label:C.bi('',''),source_ids:[t.source_ids[0]]});renderEditor();return}
 if(button.hasAttribute('data-add-route')){const t=editorBundle.team;t.chains.push({id:freshID(t.id+':route',t.chains),label:C.bi('新路线','New route'),theme:t.primary_theme,step_ids:[],edge_ids:[],dependencies:[],demonstration:false});renderEditor();return}
 if(button.hasAttribute('data-add-source')){editorBundle.sources.push({id:freshID('source:'+editorBundle.team.id,editorBundle.sources),title:'',url:'',kind:'team_supplied',description:C.bi('','')});renderEditor();return}
 for(const [attr,items] of [['deleteNode',editorBundle?.nodes],['deleteEdge',editorRelations],['deleteRoute',editorBundle?.team.chains]])if(button.dataset[attr]!==undefined){items.splice(Number(button.dataset[attr]),1);renderEditor();return}
 if(button.id==='load-example'){addExample();return}if(button.id==='preview-route'){await previewForm();return}
 if(button.id==='save-team'){const bundle=checkedForm();if(!bundle)return;try{p=C.upsert(b,p,bundle);editorBundle=C.clone(bundle);editorOriginalID=bundle.team.id;editorSeedID=bundle.team.id;editorRelations=[...editorBundle.edges,...editorBundle.dependencies,...editorBundle.enhancements];drafts[bundle.team.id]=bundle;revision++;sceneCache={};const saved=persistDrafts();selected.add(bundle.team.id);teamScope=null;teamChecks();renderEditor();$('#form-notice').textContent=saved?L('已保存到本机图谱。可在队伍页面聚焦查看，或导出文件发给维护者。','Saved locally. View it on the team page or export the bundle for the maintainers.'):L('本次页面已更新；请导出文件保存。','This page is updated; export the bundle to keep it.');toast(L('本机图谱已加入这支队伍','Team added to the local atlas'));}catch(err){$('#form-errors').hidden=false;$('#form-errors').textContent=err.message}return}
 if(button.id==='export-form'){const bundle=checkedForm();if(bundle)download(bundle.team.id+'.json',JSON.stringify(bundle,null,2));return}
 if(button.id==='copy-embed'){try{await navigator.clipboard.writeText($('#embed-code').textContent);toast(L('已复制嵌入代码','Embed code copied'))}catch{toast(L('请选中代码框中的内容复制。','Select and copy the code in the box.'))}return}
 if(button.id==='download-embed'){const code=$('#embed-code').textContent;download('space-atlas-embed.html',`<!doctype html><html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Space Material Atlas</title><body><h1>Our project in the Space Material Atlas</h1>${code}</body></html>`,'text/html');return}
});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.bind){setBinding(t.dataset.bind,t.type==='checkbox'?t.checked:t.type==='number'?Number(t.value):t.value);return}if(t.dataset.endpoint){const [i,key]=t.dataset.endpoint.split(':');editorRelations[+i][key]=resolveChoice(t.value)}if(t.id==='team-filter')teamChecks();if(t.id==='node-search')searchNodes(t.value);if(t.id==='reference-filter'){const pos=t.selectionStart;referencePage(t.value);$('#reference-filter').focus();$('#reference-filter').setSelectionRange(pos,pos)}});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.team){t.checked?selected.add(t.dataset.team):selected.delete(t.dataset.team);teamScope=null;apply();if(selected.size===1)await focusNode(selectionCore());return}if(['embed-team','embed-full-header'].includes(t.id)){const u=new URL(embedURL($('#embed-team').value));if($('#embed-full-header').checked)u.searchParams.delete('embed');$('#embed-code').textContent=`<iframe src="${u.href}" title="Space Material Atlas" width="100%" height="680" style="border:0" loading="lazy"></iframe>`}});
$('#bundle-import').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error(L('资料文件超过 5 MB','Bundle exceeds 5 MB'));const bundle=JSON.parse(await file.text()),errors=C.validateBundle(b,p,bundle);if(errors.length)throw Error(errors.join('\n'));editorBundle=bundle;editorSeedID=bundle.team.id;editorOriginalID=owners()[bundle.team.id]?bundle.team.id:null;editorRelations=[...bundle.edges,...bundle.dependencies,...bundle.enhancements];renderEditor();toast(L('资料已载入表单，尚未保存','Bundle loaded into the form; not yet saved'))}catch(err){toast(err.message)}finally{e.target.value=''}});
function searchNodes(query){
 const normalize=value=>String(value||'').normalize('NFKC').trim().replace(/\s+/g,' ').toLowerCase(),q=normalize(query);
 if(!q){$('#node-results').hidden=true;return}
 const teams=owners(),matches=Object.values(allNodes()).map((n,index)=>{
  const label=normalize(tx(n.label)),translations=(typeof n.label==='object'?Object.values(n.label):[n.label]).map(normalize),team=normalize(teams[n.owner]?.name),id=normalize(n.id);
  const rank=label===q?0:translations.includes(q)?1:label.startsWith(q)?2:translations.some(value=>value.startsWith(q))?3:label.includes(q)?4:translations.some(value=>value.includes(q))?5:team===q?6:team.startsWith(q)?7:team.includes(q)?8:id.includes(q)?9:Infinity;
  return {n,rank,index};
 }).filter(result=>Number.isFinite(result.rank)).sort((a,b)=>a.rank-b.rank||a.index-b.index).slice(0,15).map(result=>result.n);
 $('#node-results').innerHTML=matches.map(n=>`<button data-search-node="${esc(n.id)}">${esc(tx(n.label))}<small>${esc(tx(names[n.theme]||n.theme))}${n.owner?' · '+esc(teams[n.owner].name):''}</small></button>`).join('')||`<p class="tiny" style="padding:12px">${L('没有匹配的节点','No matching nodes')}</p>`;
 $('#node-results').hidden=false;window.AtlasExperience?.positionSearch()
}
$('#node-results').addEventListener('click',async e=>{const id=e.target.closest('[data-search-node]')?.dataset.searchNode;if(!id)return;$('#node-results').hidden=true;$('#node-search').value='';$('#node-search').blur();await focusNode(id)});
$('#view').addEventListener('change',()=>{view=$('#view').value;picked=null;showGraph()});$('#lang').addEventListener('change',()=>{lang=$('#lang').value;refreshLanguage();if(pageName==='contribute'&&editorBundle)renderEditor();else showPage(pageName)});
$('#baseline').addEventListener('click',()=>{selected.clear();teamScope=null;ground=false;view='overview';picked=null;$('#ground').checked=false;showGraph()});$('#all').addEventListener('click',()=>{selected=new Set(p.teams.map(t=>t.id));teamScope=null;apply();fit()});$('#none').addEventListener('click',()=>{selected.clear();teamScope=null;apply()});$('#ground').addEventListener('change',()=>{ground=$('#ground').checked;apply();fit()});$('#fit').addEventListener('click',()=>fit(true));$('#clear-focus').addEventListener('click',resetFocus);$('#toggle-detail').addEventListener('click',()=>$('#graph-shell').classList.toggle('closed'));
$('#canvas').addEventListener('click',e=>{const badge=e.target.closest('.badge');if(badge){e.preventDefault();edgeDetail([badge.dataset.effectId]);return}const node=e.target.closest('.node');if(node){e.preventDefault();focusNode(node.dataset.node,false);return}const edge=e.target.closest('.edge');if(edge){e.preventDefault();edgeDetail(edge.dataset.ids.split(' '));return}});
$('#canvas').addEventListener('pointerover',e=>{if(picked||drag||e.pointerType==='touch')return;const n=e.target.closest('.node');if(n)highlightOne(n.dataset.node)});$('#canvas').addEventListener('pointerout',e=>{if(picked||drag||e.pointerType==='touch')return;const n=e.target.closest('.node');if(n&&!n.contains(e.relatedTarget))clearFocus(false)});
$('#svg-export').addEventListener('click',()=>{clearFocus(false);const node=svg.cloneNode(true);node.querySelectorAll('[data-motion-layer],[data-hit-area]').forEach(n=>n.remove());node.querySelectorAll('[style*="display: none"]').forEach(n=>n.remove());node.setAttribute('width',box[2]);node.setAttribute('height',box[3]);download(`space-atlas-${view}-${lang}.svg`,new XMLSerializer().serializeToString(node),'image/svg+xml')});$('#json-export').addEventListener('click',()=>download('space-atlas-data.json',JSON.stringify({baseline:b,projects:p,selection:state()},null,2)));

/* Read-only embed protocol: validate both parent window and exact origin. */
function parentOrigin(){const configured=params.get('parentOrigin');try{const u=new URL(configured||document.referrer);return ['http:','https:'].includes(u.protocol)?u.origin:null}catch{return null}}
const trustedParent=parentOrigin();
function state(){return {view,lang,mode:readOnly?'display':'edit',embedded,teams:[...selected],ground,teamScope,focus:picked?.kind==='node'?(scene?.model.nodes[picked.id]?.logical_id||picked.id):null}}
function emit(event,payload){if(window.parent!==window&&trustedParent)window.parent.postMessage({type:`space-atlas:${event}`,version:1,...payload},trustedParent)}
window.addEventListener('message',async e=>{if(e.source!==window.parent||!trustedParent||e.origin!==trustedParent)return;const m=e.data;if(!m||m.version!==1||typeof m.type!=='string')return;try{
 if(m.type==='space-atlas:set-teams'&&Array.isArray(m.teams)){const known=new Set(p.teams.map(t=>t.id));if(m.teams.some(id=>!known.has(id)))return;selected=new Set(m.teams);picked=null;teamScope=m.focus&&m.teams.length===1?m.teams[0]:null;await showGraph(selectionCore())}
 else if(m.type==='space-atlas:set-view'&&DATA.views.includes(m.view)){view=m.view;picked=null;await showGraph()}
 else if(m.type==='space-atlas:focus-node'&&typeof m.id==='string'&&allNodes()[m.id]){await focusNode(m.id)}
 else if(m.type==='space-atlas:set-language'&&['zh','en'].includes(m.lang)){lang=m.lang;picked=null;await showGraph()}
 else if(m.type==='space-atlas:set-ground'&&typeof m.ground==='boolean'){ground=m.ground;$('#ground').checked=ground;apply();fit()}
 else if(m.type==='space-atlas:reset-focus')resetFocus()
 else if(m.type==='space-atlas:fit'){fit()}
 else if(m.type==='space-atlas:get-state')emit('state',state());
 }catch(err){emit('error',{message:err.message})}});
if(embedded)document.body.classList.add('embedded');if(readOnly)document.body.classList.add('read-only');
ground=params.get('ground')==='1';$('#ground').checked=ground;loadDrafts();const requested=params.get('team');if(requested){selected=new Set(requested.split(',').filter(id=>owners()[id]));if(params.get('focusTeam')==='1'&&selected.size===1)teamScope=[...selected][0]}
refreshLanguage();showGraph(params.get('focus')||selectionCore()).then(()=>{emit('ready',{...state(),catalog:{teams:p.teams.map(t=>({id:t.id,name:t.name,year:t.year})),views:DATA.views,nodes:[...b.nodes,...p.nodes].map(n=>({id:n.id,label:n.label}))}});const hash=location.hash.slice(1);if(hash==='contribute'&&!readOnly)openEditor();else if(['teams','references','about','embed'].includes(hash))showPage(hash)});
